using Godot;
using System;
using System.Collections.Generic;

public partial class TransformationWorkspaceOperations
{
    private static bool Locked(Control owner)=>Session(owner).Call("primary").As<Resource>() is not Resource item||item.Get("locked").AsBool();
    private static void Status(Control owner,string text)=>Item<Label>(owner,"status").Text=text;
    public void shape_created(Control owner,string kind,Rect2 bounds)
    {
        var state=Active(owner);if(kind!="shape"||state==null||Locked(owner))return;var art=state.Get("artwork").As<Resource>();using var image=art.Get("texture").As<Texture2D>().GetImage();image.Convert(Image.Format.Rgba8);var frame=art.Call("local_transform").AsTransform2D();var scale=art.Get("dimensions").AsVector2()/(Vector2)image.GetSize();var region=frame.AffineInverse()*bounds;region=new Rect2(region.Position/scale,region.Size/scale).Intersection(new Rect2(Vector2.Zero,(Vector2)image.GetSize()));string shape=owner.Get("shape_kind").AsString();var color=Item<Control>(owner,"canvas").Get("color").AsColor();for(int y=(int)Math.Floor(region.Position.Y);y<(int)Math.Ceiling(region.End.Y);y++)for(int x=(int)Math.Floor(region.Position.X);x<(int)Math.Ceiling(region.End.X);x++){var point=frame*(new Vector2(x+.5f,y+.5f)*scale);if(!bounds.HasPoint(point))continue;if(shape=="ellipse"&&((point-bounds.GetCenter())/(bounds.Size*.5f)).LengthSquared()>1)continue;image.SetPixel(x,y,image.GetPixel(x,y).Blend(color));}Session(owner).Call("begin");art.Set("texture",ImageTexture.CreateFromImage(image));state.Set("revision",state.Get("revision").AsInt64()+1);Session(owner).Call("commit","Draw "+shape);
    }
    public void extract_selection(Control owner)
    {
        finish_pending(owner);var state=Active(owner);var item=Session(owner).Call("primary").As<Resource>();var canvas=Item<Control>(owner,"canvas");if(state==null||item==null||item.Get("locked").AsBool()||canvas.Get("selection").As<Image>()==null){Status(owner,"Select pixels on an unlocked drawing first.");return;}var art=state.Get("artwork").As<Resource>();using var old=art.Get("texture").As<Texture2D>().GetImage();using var remaining=(Image)old.Duplicate();using var extracted=(Image)old.Duplicate();var frame=art.Call("local_transform").AsTransform2D();var scale=art.Get("dimensions").AsVector2()/(Vector2)old.GetSize();for(int y=0;y<old.GetHeight();y++)for(int x=0;x<old.GetWidth();x++){float coverage=canvas.Call("selection_coverage",frame*(new Vector2(x+.5f,y+.5f)*scale)).AsSingle();var value=old.GetPixel(x,y);var kept=value;kept.A*=1-coverage;value.A*=coverage;remaining.SetPixel(x,y,kept);extracted.SetPixel(x,y,value);}if(extracted.GetUsedRect().Size==Vector2I.Zero){Status(owner,"The selection contains no visible pixels.");return;}var session=Session(owner);session.Call("begin");art.Set("texture",ImageTexture.CreateFromImage(remaining));state.Set("revision",state.Get("revision").AsInt64()+1);using var resources=new TransformationResourceOperations();var copy=resources.make_component(Document(owner).Get("canvas_size").AsVector2I(),"Extracted drawing");copy.Set("base_size",item.Get("base_size"));var copiedState=copy.Get("states").AsGodotArray()[0].AsGodotObject();var copiedArt=art.Call("copy_layer").As<Resource>();copiedArt.Set("id",copy.Get("id"));copiedArt.Set("texture",ImageTexture.CreateFromImage(extracted));copiedState.Set("artwork",copiedArt);copiedState.Set("pivot",state.Get("pivot"));Document(owner).Get("components").AsGodotArray().Add(copy);var selected=session.Get("selected").AsGodotArray();selected.Clear();selected.Add(copy.Get("id"));session.Call("commit","Extract selected pixels");
    }
    public void detach_at_playhead(Control owner)
    {
        finish_pending(owner);var state=Active(owner);var canvas=Item<Control>(owner,"canvas");if(state==null||canvas.Get("selection").As<Image>()==null){Status(owner,"Select pixels on a component first.");return;}var art=state.Get("artwork").As<Resource>();using var image=art.Get("texture").As<Texture2D>().GetImage();using var mask=Image.CreateEmpty(image.GetWidth(),image.GetHeight(),false,Image.Format.Rgba8);var frame=art.Call("local_transform").AsTransform2D();var scale=art.Get("dimensions").AsVector2()/(Vector2)image.GetSize();for(int y=0;y<image.GetHeight();y++)for(int x=0;x<image.GetWidth();x++)mask.SetPixel(x,y,new Color(1,1,1,canvas.Call("selection_coverage",frame*(new Vector2(x+.5f,y+.5f)*scale)).AsSingle()));using var events=new TransformationComponentEvents();string message=events.detach(Session(owner),mask);if(message.Length>0)Status(owner,message);else{seek(owner,Session(owner).Get("playhead").AsDouble());Status(owner,"Region detached at the playhead. Original states are unchanged; edit the new component's states to animate it.");}
    }
    public void import_image(Control owner,string source)
    {
        var state=Active(owner);if(state==null||Locked(owner))return;using var image=Image.LoadFromFile(source);if(image==null||image.IsEmpty()){Status(owner,"This image could not be read.");return;}if(image.GetWidth()>8192||image.GetHeight()>8192||(long)image.GetWidth()*image.GetHeight()>16777216){Status(owner,"Maximum state artwork is 8192 pixels per side / 16 megapixels.");return;}edit_mode(owner);Session(owner).Call("begin");state.Get("artwork").AsGodotObject().Set("texture",ImageTexture.CreateFromImage(image));state.Set("revision",state.Get("revision").AsInt64()+1);Session(owner).Call("commit","Load state artwork");
    }
    public void add_reveal_point(Control owner,Vector2 value){var selected=selected_key(owner);if(selected.Count==0){Status(owner,"Select the outgoing keyframe first.");return;}if(selected["key"].AsGodotObject().Get("reveal_path").AsVector2Array().Length>=64)return;ChangeKeys(owner,"Reveal path point",(item,key)=>{var points=new List<Vector2>(key.Get("reveal_path").AsVector2Array());points.Add(value);key.Set("reveal_path",points.ToArray());key.Set("mode","Grow / Reveal");key.Set("reveal_mode","Path");});}
    public void remove_component_event(Control owner,string id){var events=Document(owner).Get("component_events").AsGodotArray();foreach(var raw in events){var entry=raw.AsGodotDictionary();if(entry["id"].AsString()!=id)continue;Session(owner).Call("begin");Document(owner).Call("component",entry["target"]).AsGodotObject().Set("visible",false);for(int index=events.Count-1;index>=0;index--)if(events[index].AsGodotDictionary()["id"].AsString()==id)events.RemoveAt(index);Session(owner).Call("commit","Delete component event");return;}}
}
